#pragma once

#include <atomic>
#include <cstdint>
#include <mutex>

#include "driver/gpio.h"
#include "driver/gptimer.h"
#include "esp_err.h"
#include "freertos/FreeRTOS.h"
#include "freertos/semphr.h"

// STEP/DIR/EN stepper driver (TMC2209).
//
// STEP pulses are generated by a hardware timer interrupt, so the CPU (and
// Wi-Fi) keep running while the motor moves; the calling task just blocks
// until the move is finished.
class Motor {
public:
    Motor(gpio_num_t en_pin, gpio_num_t step_pin, gpio_num_t dir_pin, uint32_t step_delay_us);

    esp_err_t init();

    // TMC2209: EN LOW = motor enabled, EN HIGH = motor disabled
    void set_motor_enabled(bool enabled);

    // TMC2209 microstepping is set in hardware, kept for compatibility with Scanner
    void set_microstepping_resolution(int resolution) { resolution_ = resolution; }

    // Blocking move to absolute position (in microsteps).
    // Caller must hold mutex() for the duration of a motion sequence.
    void run_to_position_steps(int32_t target);

    int32_t position() const { return position_; }
    void reset_position(int32_t position = 0) { position_ = position; }

    void set_step_delay_us(uint32_t step_delay_us) { step_delay_us_ = step_delay_us; }

    // Serializes motion sequences (scan, jog, tests)
    std::mutex& mutex() { return mutex_; }

    void close();

private:
    static bool on_alarm(gptimer_handle_t timer, const gptimer_alarm_event_data_t* edata, void* user_ctx);
    void pulse(uint32_t steps);

    gpio_num_t en_pin_;
    gpio_num_t step_pin_;
    gpio_num_t dir_pin_;
    uint32_t step_delay_us_;
    int resolution_ = 1;

    std::atomic<int32_t> position_{0};
    std::mutex mutex_;

    gptimer_handle_t timer_ = nullptr;
    SemaphoreHandle_t done_ = nullptr;
    volatile uint32_t remaining_edges_ = 0;
    volatile bool step_level_ = false;
};
